import os,sys,json,traceback
import numpy as np
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot,EpisodeOver
from scipy.spatial.transform import Rotation as Rotation

OUT='/app/output/state'
os.makedirs(OUT,exist_ok=True)
r=Robot()
Q_DOWN=[0.,-.70710678,.70710678,0.]
Q_SIDE=[.5,.5,-.5,.5] # tool x vertical, tool z toward -y

def save(res,name):
    res.save(f'{OUT}/{name}')
    print(name,'done',res.meta.get('done'),'reason',res.meta.get('reason'),'steps',res.meta.get('control_steps_chunk'),'plan',res.meta.get('plan'),'proprio',np.round(res.meta['proprio']['now'][8:16],4),'opening',res.meta['proprio']['now'][24],flush=True)
    return res

def pose(name,points):
    try:
        return save(r.submit('ee_pose',points,video='none',depth=True,note=name),name)
    except Exception as e:
        print('ERROR',name,repr(e),flush=True)
        if 'Connection' in type(e).__name__ or 'Timeout' in type(e).__name__:
            print('RECOVER',r.wait_ready(),flush=True)
        raise

phase=sys.argv[1] if len(sys.argv)>1 else 'observe'
if phase=='lift':
    pose('01_lift',[[.36,0,.45,*Q_DOWN,0]])
elif phase=='rotate':
    pose('02_rotate',[[.36,0,.45,*Q_SIDE,0]])
elif phase=='pregrasp':
    pose('03_pregrasp',[[.55,.15,.45,*Q_SIDE,0],[.65,.14,.35,*Q_SIDE,0]])
elif phase=='descend':
    pose('04_descend',[[.65,.14,.29,*Q_SIDE,0],[.65,.14,.22,*Q_SIDE,0]])
elif phase=='approach':
    pose('05_approach',[[.65,.105,.22,*Q_SIDE,0],[.65,.07,.22,*Q_SIDE,0]])
elif phase=='close':
    pose('06_close',[[.65,.07,.22,*Q_SIDE,1]])
elif phase=='observe':
    obs=r.get_obs(depth=True)
    save(obs,'observation')
    print(r.status())
PY
